changeSet.sql:
ALTER TABLE estates ADD COLUMN fees_declared_at timestamptz, ADD COLUMN fees_version integer NOT NULL DEFAULT 0, ADD COLUMN fees_declaration_exempt boolean NOT NULL DEFAULT false;
-- Grandfathering, applied once: every estate already on the -- marketplace keeps its listing. Requiring a declaration -- retroactively would delist real, live listings to make a -- point — principle over usefulness. New publications get no -- such exemption. UPDATE estates SET fees_declaration_exempt = true WHERE published = true AND deleted = false;
COMMENT ON COLUMN estates.fees_declared_at IS 'When this estate''s fee schedule was last declared. NULL means nobody has said anything ' '— which is NOT the same as declaring no fees, and blocks publication. Declaring an ' 'empty schedule sets this and is permitted.';
COMMENT ON COLUMN estates.fees_declaration_exempt IS 'One-time grandfathering: true for estates already published when full cost disclosure ' 'shipped. They predate the requirement and keep their listing. TODO: backfill real ' 'schedules for these, then clear the flag and drop this column and its term in ' 'marketplace_estate_eligibility.';
